const entrySidebarToggleModule = await import(`data:text/javascript;charset=utf-8,${encodeURIComponent(entrySidebarToggleSource)}`)
const shouldCloseEntrySidebarForRequest = entrySidebarToggleModule.shouldCloseEntrySidebarForRequest
const entryFormStateSource = read('src/utils/entryFormState.js')
const entryFormStateModule = await import(`data:text/javascript;charset=utf-8,${encodeURIComponent(entryFormStateSource)}`)
const { hasEntryFormChanges, snapshotEntryForm } = entryFormStateModule
const entryFormBaseline = snapshotEntryForm({
	type: 'expense',
	amountDisplay: '6,00',
	description: 'Lunch',
	date: new Date('2026-08-02T00:00:00.000Z')
})
assertEqual(hasEntryFormChanges(entryFormBaseline, {
	type: 'expense',
	amountDisplay: '6,00',
	description: 'Lunch',
	date: new Date('2026-08-02T00:00:00.000Z')
}), false, 'Entry form snapshots keep unchanged payment details clean')
assertEqual(hasEntryFormChanges(entryFormBaseline, {
	type: 'income',
	amountDisplay: '6,00',
	description: 'Lunch',
	date: new Date('2026-08-02T00:00:00.000Z')
}), true, 'Entry form snapshots detect a payment-type change')
assertEqual(hasEntryFormChanges(entryFormBaseline, {
	type: 'expense',
	amountDisplay: '6,00',
	description: 'Lunch',
	date: new Date('2026-08-02T00:00:00.000Z')
}, 1), true, 'Pending receipts count as unsaved payment changes')
const plainNewSidebar = {
	isOpen: true,
	isEditing: false,
	isCreatingNewEntry: true,
	isFutureContext: false,
	newEntryDefaultType: 'expense'
}
const editingSidebar = {
	isOpen: true,
	isEditing: true,
	isCreatingNewEntry: false,
	isFutureContext: false,
	newEntryDefaultType: 'expense'
}
assertEqual(shouldCloseEntrySidebarForRequest({ sidebar: plainNewSidebar }), true, 'Entry sidebar repeats the plain new-payment action as close')
assertEqual(shouldCloseEntrySidebarForRequest({ sidebar: { ...plainNewSidebar, isOpen: false } }), false, 'Entry sidebar opens from a closed state')
assertEqual(shouldCloseEntrySidebarForRequest({ sidebar: plainNewSidebar, editingFuture: true }), false, 'Entry sidebar switches between current and planned new payments')
assertEqual(shouldCloseEntrySidebarForRequest({ sidebar: editingSidebar, entryToEdit: { id: 10 }, requestedSelectedEntryId: 10, selectedEntryId: '10' }), true, 'Entry sidebar closes when the selected row is activated again')
assertEqual(shouldCloseEntrySidebarForRequest({ sidebar: editingSidebar, entryToEdit: { id: 11 }, requestedSelectedEntryId: 11, selectedEntryId: 10 }), false, 'Entry sidebar switches directly between different rows')
assertEqual(shouldCloseEntrySidebarForRequest({ sidebar: editingSidebar }), false, 'Entry sidebar switches directly from editing to a new payment')
assertEqual(shouldCloseEntrySidebarForRequest({ sidebar: plainNewSidebar, entryToEdit: { id: 10 }, requestedSelectedEntryId: 10, selectedEntryId: 10 }), false, 'Entry sidebar switches directly from a new payment to editing')
assertEqual(shouldCloseEntrySidebarForRequest({ sidebar: plainNewSidebar, entryToDuplicate: { id: 10 } }), false, 'Entry sidebar keeps copy requests distinct from a plain new payment')
