assertContains(projectList, ':primary-disabled="!newProject.name.trim() || creatingProject"', 'Project create button trims and respects busy state')
assertContains(projectList, ':primary-busy="creatingProject"', 'Project create button shows busy state')
assertContains(projectList, 'v-if="$enableSharedProjects"', 'Project create modal hides member search when shared areas are disabled')
assertContains(projectList, 'members: this.$enableSharedProjects ? this.newProject.members.map(m => m.id) : []', 'Project create payload ignores extra members when shared areas are disabled')
assertContains(projectList, 'v-if="isSharedProject(project)" class="project-card-balance"', 'Area overview hides meaningless balances for personal areas')
assertContains(projectList, '$texts.areas.personalArea()', 'Area overview labels one-member areas as personal')
assertContains(projectList, 'project?.is_shared !== undefined', 'Area overview prefers the authoritative server-side shared flag')

assertContains(projectDetail, 'openProjectSettings()', 'Project detail opens a dedicated settings page')
assertContains(projectSettings, 'canAddProjectMembers() {\n\t\t\treturn !!this.project && this.$enableSharedProjects && this.canManageProject && !this.hasFormerMembers;', 'Project settings hides member add action when shared areas are disabled, user is not owner, or a former member is unresolved')
assertContains(projectSettings, 'canRemoveProjectMembers() {\n\t\t\treturn !!this.project && this.$enableSharedProjects && this.canManageProject;', 'Project settings hides member remove action when shared areas are disabled or user is not owner')
assertContains(projectSettings, 'v-if="member.id !== project.owner_id"', 'Project settings lets the owner remove a former non-owner after settlement')
assertContains(projectSettings, '$texts.areaSettings.resolveFormerMember()', 'Project settings explains how to resolve a former member without losing history')
assertContains(projectSettings, 'icon-only', 'Project settings uses an icon action for member removal')
assertContains(projectSettings, "showRequestError(e, this.$texts.areaDetail.memberAddError(member.displayName || member.id), 'Failed to add member')", 'Project settings shows member add errors')
assertContains(projectSettings, "showRequestError(e, this.$texts.areaDetail.memberRemoveError(), 'Failed to remove member')", 'Project settings shows member remove errors')
assertContains(projectSettings, 'const name = this.editProjectData.name.trim();', 'Project settings trims whitespace-only names')
assertContains(projectSettings, ':disabled="!canSaveProject"', 'Project settings disables unchanged or invalid saves')

const packageJson = JSON.parse(read('package.json'))
if (packageJson.scripts?.['test:frontend-smoke'] !== 'node tests/frontend-smoke.mjs') {
	failures.push('package.json is missing test:frontend-smoke script')
}

if (failures.length > 0) {
	console.error('Frontend smoke checks failed:')
	for (const failure of failures) {
		console.error(`- ${failure}`)
	}
	process.exit(1)
}

console.log('Frontend smoke checks passed.')
